/**
 * Papo — design tokens (paleta padrão de produção).
 * Valores espelham Papo → Configurações → Aparência — cores padrão.
 * Sobrescritas do painel são injetadas via Papo_Design_Tokens::build_css().
 */
:root {
    --papo-color-brand: #2d6a4f;
    --papo-color-brand-dark: #1b4332;
    --papo-color-brand-soft: #f0f9f4;
    --papo-color-brand-border: #b7e4c7;
    --papo-color-primary: #2d6a4f;
    --papo-color-primary-dark: #1b4332;
    --papo-color-text: #1a2e35;
    --papo-color-muted: #5f7c72;
    --papo-color-border: #e2e8e4;
    --papo-color-soft: #f7faf8;
    --papo-color-page-bg: #fafcfb;
    --papo-color-danger: #dc3545;
    --papo-color-warning: #f59e0b;
    --papo-color-brand-grad: linear-gradient(90deg, var(--papo-color-brand) 0%, var(--papo-color-brand-dark) 100%);

    /* Aliases semânticos (PT) — compatível com documentação do painel */
    --papo-color-verde-principal: var(--papo-color-brand);
    --papo-color-verde-escuro: var(--papo-color-brand-dark);
    --papo-color-fundo-verde-suave: var(--papo-color-brand-soft);
    --papo-color-borda-verde-suave: var(--papo-color-brand-border);
    --papo-color-azul-primario: var(--papo-color-primary);
    --papo-color-azul-escuro: var(--papo-color-primary-dark);
    --papo-color-texto-principal: var(--papo-color-text);
    --papo-color-texto-secundario: var(--papo-color-muted);
    --papo-color-bordas-divisorias: var(--papo-color-border);
    --papo-color-fundo-suave: var(--papo-color-soft);
    --papo-color-fundo-pagina: var(--papo-color-page-bg);
    --papo-color-erro-alerta: var(--papo-color-danger);
    --papo-color-aviso: var(--papo-color-warning);
}

/* ═══════════════════════════════════════════════════════
   Theme: Solid (default)
   ═══════════════════════════════════════════════════════ */
body.papo-theme-solid,
:root {
    --papo-surface-bg: #fff;
    --papo-surface-border: var(--papo-color-border);
    --papo-surface-radius: 14px;
    --papo-surface-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
    --papo-surface-blur: none;
    --papo-overlay-bg: rgba(15, 23, 42, 0.5);
    --papo-modal-bg: #fff;
    --papo-modal-border: var(--papo-color-border);
    --papo-modal-radius: 18px;
    --papo-modal-shadow: 0 20px 60px -15px rgba(15, 23, 42, 0.25);
    --papo-modal-blur: none;
}

/* ═══════════════════════════════════════════════════════
   Theme: Glass (glassmorphism)
   ═══════════════════════════════════════════════════════ */
body.papo-theme-glass {
    --papo-surface-bg: rgba(255, 255, 255, 0.55);
    --papo-surface-border: rgba(255, 255, 255, 0.45);
    --papo-surface-radius: 20px;
    --papo-surface-shadow: 0 8px 32px -8px rgba(15, 23, 42, 0.18), inset 0 1px 0 rgba(255, 255, 255, 0.5);
    --papo-surface-blur: blur(24px) saturate(150%);
    --papo-overlay-bg: rgba(15, 23, 42, 0.4);
    --papo-modal-bg: rgba(255, 255, 255, 0.7);
    --papo-modal-border: rgba(255, 255, 255, 0.5);
    --papo-modal-radius: 24px;
    --papo-modal-shadow: 0 24px 64px -16px rgba(15, 23, 42, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.6);
    --papo-modal-blur: blur(32px) saturate(170%);
    background:
        radial-gradient(1200px 800px at 10% -10%, color-mix(in srgb, var(--papo-color-brand-soft) 28%, transparent) 0%, transparent 58%),
        radial-gradient(1000px 700px at 100% 15%, color-mix(in srgb, var(--papo-color-page-bg, #fafcfb) 60%, #e8f4fc) 0%, transparent 55%),
        radial-gradient(900px 700px at 50% 105%, color-mix(in srgb, var(--papo-color-brand-border) 16%, transparent) 0%, transparent 62%),
        var(--papo-color-page-bg, #fafcfb) !important;
