    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    transition: all 0.3s ease;
}

.prompt-improver-close:hover {
    color: #000;
    background: rgba(255, 255, 255, 1);
    transform: rotate(90deg);
}

.prompt-improver-steps {
