    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.spinner {
    border: 6px solid rgba(0, 0, 0, 0.1);
    width: 50px;
    height: 50px;
    border-radius: 50%;
    border-left-color: #4CAF50;
