/* Estilos para a seção de sugestões automáticas */
.automatic-suggestions-section {
    margin-bottom: 30px;
    padding: 25px;
    background-color: #f8f9fa;
    border-radius: 8px;
    border: 1px solid #e2e4e7;
}

.automatic-suggestions-section h4 {
