}

/* Painéis */
.papo-panel {
    margin-bottom: 15px;
}

.papo-panel-title {
    padding: 8px;
    margin: 0;
    font-size: 16px;
    color: #333;
}

.papo-panel-content {
    padding: 8px;
}

.papo-panel-content p {
    margin: 0;
    font-size: 14px;
    color: #666;
}

/* Formulários */
.papo-form-container {
    margin-top: 15px;
}

.papo-form-group {
    margin-bottom: 10px;
}

.papo-form-label {
    display: block;
    margin-bottom: 5px;
    font-weight: 500;
    color: #333;
    font-size: 14px;
}

.papo-form-input,
.papo-form-select {
