/* Estilos do Modal */
.modal {
    display: none;
    position: fixed;
    z-index: 1000;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0,0,0,0.4);
}

.modal-content {
    position: relative;
    background-color: #fefefe;
    margin: 5% auto;
    padding: 20px;
    border: 1px solid #888;
    width: 80%;
    max-width: 600px;
    border-radius: 5px;
    animation: modalFadeIn 0.3s;
}

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
    padding-bottom: 10px;
    border-bottom: 1px solid #ddd;
}

.modal-close {
    color: #aaa;
    font-size: 28px;
    font-weight: bold;
    cursor: pointer;
}

.modal-close:hover {
    color: #000;
}

.confirmacoes-container {
    margin-top: 20px;
}

.confirmacoes-header {
    margin-bottom: 20px;
}

.confirmacoes-list {
    max-height: 400px;
    overflow-y: auto;
}

.confirmacao-item {
    margin-bottom: 15px;
    padding: 10px;
    background: #f8f9fa;
    border-radius: 4px;
}

.confirmacao-item label {
    display: flex;
    align-items: center;
    cursor: pointer;
}

.confirmacao-checkbox {
    margin-right: 10px;
}

.confirmacao-text {
    flex: 1;
}

@keyframes modalFadeIn {
    from {
        opacity: 0;
        transform: translateY(-20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
    
/* Removendo estilos do campo de importação de mensagens */
#import_messages, label[for="import_messages"] {
    display: none !important;
}

#days_limit_import_messages, label[for="days_limit_import_messages"] {
    display: none !important;
}
    
/* Bloco dos webhooks no fluxo da página ([gerenciar_webhooks] ou último item do painel completo). */
