    font-weight: 600;
}

.shortcode-documentation .widefat td:first-child {
    font-weight: 600;
    color: var(--papo-color-primary, #0073aa);
}

.shortcode-documentation .widefat td:last-child {
    font-size: 12px;
    color: #666;
    font-style: italic;
}

/* Responsividade para tabelas */
