#customer_login .woocommerce-form input[type="password"],
#customer_login .woocommerce-form input[type="number"] {
  width: 100%;
  padding: 7px 10px;
  border: 1px solid #dbeafe;
  border-radius: 6px;
  background: var(--papo-color-soft, #f8fafc);
  font-size: 0.875rem;
  margin-top: 2px;
  margin-bottom: 8px;
  transition: border 0.2s;
  outline: none;
  box-shadow: none;
}

.woocommerce-form input:focus {
  border-color: var(--papo-color-brand, #61ce70);
  background: #fff;
  box-shadow: 0 2px 8px rgba(97,206,112,0.10);
}

.woocommerce-form .form-row {
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
}

.woocommerce-form .form-row input[type="checkbox"] {
  margin-right: 7px;
  accent-color: var(--papo-color-brand, #61ce70);
}

#customer_login .woocommerce-form .woocommerce-button,
#customer_login .woocommerce-form .button {
  background: linear-gradient(90deg, var(--papo-color-brand, #61ce70) 60%, var(--papo-color-brand-dark, #28a745) 100%);
