  border: none;
  border-radius: 6px;
  padding: 8px 12px;
  width: 100%;
  font-size: 0.875rem;
  font-weight: 700;
  box-shadow: 0 1px 6px rgba(97, 206, 112, 0.15);
  transition: background 0.2s, box-shadow 0.2s;
  margin-left: 0;
}

#customer_login .woocommerce-form .woocommerce-button:hover,
#customer_login .woocommerce-form .button:hover {
  background: linear-gradient(90deg, var(--papo-color-brand-dark, #28a745) 60%, var(--papo-color-brand, #61ce70) 100%);
