  font-weight: 600;
  text-decoration: none;
  font-size: 0.8rem;
}

#customer_login .woocommerce-LostPassword a:hover {
  color: var(--papo-color-brand, #61ce70);
  text-decoration: underline;
}

#customer_login .password-input {
  position: relative;
  width: 100%;
  display: flex;
  align-items: center;
}

#customer_login .password-input input[type="password"],
#customer_login .password-input input[type="text"] {
  flex: 1;
  margin-bottom: 8px;
}

#customer_login .password-input .show-password-input {
  background: none;
  border: none;
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  width: 22px;
  height: 22px;
  cursor: pointer;
  opacity: 0.7;
}

#customer_login .password-input .show-password-input:after {
  content: "👁️";
  font-size: 0.85em;
}

#customer_login .balao-passo-2 {
  top: -22px !important;
  right: 0 !important;
  font-size: 0.7rem !important;
  padding: 3px 10px !important;
  border-radius: 10px 10px 10px 0 !important;
  border: 1px solid var(--papo-color-brand-dark, #218838) !important;
}

#customer_login .woocommerce-form .required {
  color: #e63946;
  font-weight: bold;
  margin-left: 2px;
}

.woocommerce-form .screen-reader-text {
  display: none;
}

.woocommerce-form .form-row label {
  margin-bottom: 0;
}

.woocommerce-form .form-row span {
  font-size: 1rem;
}

.woocommerce-form input[type="checkbox"] {
  width: 18px;
  height: 18px;
}

.woocommerce-form .woocommerce-form__label-for-checkbox {
  font-size: 1.05rem;
  color: #444;
  font-weight: 500;
  opacity: 0.85;
}

@media (max-width: 900px) {
