    color: #444;
    font-size: 13px;
}

div.papo-users-error:not(#papo-users-message) {
    padding: 12px 14px;
    border-radius: 6px;
    font-size: 13px;
    background-color: #f2f2f2;
    color: #1f1f1f;
    border: 1px solid #bdbdbd;
    margin: 12px 0;
}

@media (max-width: 480px) {
    .papo-users-container {
        padding: 16px;
    }

    .papo-users-header {
        flex-direction: column;
        align-items: flex-start;
    }

    .papo-users-current {
        text-align: left;
    }
}

/* Minha conta > Assinaturas — uso de usuários Papo */
.papo-subscription-users-notice {
    margin: 0 0 1.25em;
}

.papo-subscription-users-notice__line {
    margin: 0 0 0.5em;
}

.papo-subscription-users-notice__line:last-child {
    margin-bottom: 0;
    font-size: 0.92em;
    opacity: 0.85;
}

