/* ===== SISTEMA DE TELA CHEIA SEPARADO ===== */

html.papo-prompt-fullscreen-active,
html.papo-prompt-fullscreen-active body {
    overflow: hidden !important;
    background: #fff !important;
}

body.papo-prompt-fullscreen-active .papo-tutorial-fab,
body.papo-prompt-fullscreen-active .assistentes-selector {
    display: none !important;
}

/* Shell fullscreen — formulário movido para o body via JS */
body.is-main-fullscreen .informacoes-empresa-form,
body.is-sub-fullscreen .sub-prompt-form {
    position: fixed !important;
    inset: 0 !important;
    z-index: 1000000 !important;
    display: flex !important;
    flex-direction: column !important;
    width: 100% !important;
    max-width: none !important;
    height: 100% !important;
    max-height: none !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow: hidden !important;
    box-sizing: border-box !important;
    background: #fff !important;
    border: none !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}

/* === PROMPT PRINCIPAL === */
body.is-main-fullscreen .informacoes-empresa-form {
    padding-top: max(52px, calc(env(safe-area-inset-top, 0px) + 44px)) !important;
}

body.is-main-fullscreen #papo-prompt-sections {
    flex: 1 1 auto !important;
    min-height: 0 !important;
    overflow-y: auto !important;
    margin: 0 !important;
    padding: 0 20px 16px !important;
    -webkit-overflow-scrolling: touch;
}

body.is-main-fullscreen .papo-section {
    margin-bottom: 12px !important;
    border: 1px solid #e2e8f0 !important;
    border-radius: 10px !important;
    overflow: hidden !important;
    background: #fff !important;
}

body.is-main-fullscreen .papo-section-collapsed .papo-section-content {
    display: block !important;
}

body.is-main-fullscreen .papo-section-content {
    padding: 0 12px 12px 2.5rem !important;
    background: #fff !important;
}

body.is-main-fullscreen .papo-section-textarea {
    min-height: 110px !important;
    max-height: none !important;
    padding: 12px 36px 12px 12px !important;
    font-size: 13px !important;
    line-height: 1.55 !important;
    color: #0f172a !important;
    background: #fff !important;
    border: 1px solid #e2e8f0 !important;
    border-radius: 8px !important;
}

body.is-main-fullscreen .papo-prompt-actions {
    flex-shrink: 0 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 12px !important;
    margin: 0 !important;
    padding: 12px 20px max(12px, env(safe-area-inset-bottom, 0px)) !important;
    border-top: 1px solid #e2e8f0 !important;
    background: #fff !important;
    box-shadow: 0 -6px 24px rgba(15, 23, 42, 0.06) !important;
}

body.is-main-fullscreen .papo-prompt-actions__buttons .papo-action-btn:not(#update-btn),
body.is-main-fullscreen .papo-prompt-actions__buttons .main-fullscreen-btn,
body.is-main-fullscreen .papo-section-mic-btn,
body.is-main-fullscreen .personas-selector,
body.is-main-fullscreen .papo-accordion-help,
body.is-main-fullscreen .prompt-improver-popup,
body.is-main-fullscreen h2,
body.is-main-fullscreen h3 {
    display: none !important;
}

body.is-main-fullscreen .character-count {
    display: inline-flex !important;
    align-items: center !important;
    gap: 0.25rem !important;
}

/* === SUB-PROMPT === */
body.is-sub-fullscreen .sub-prompt-form-content {
    flex: 1 1 auto !important;
    min-height: 0 !important;
    display: flex !important;
    flex-direction: column !important;
    overflow: hidden !important;
    padding-top: max(52px, calc(env(safe-area-inset-top, 0px) + 44px)) !important;
}

body.is-sub-fullscreen .field-group:has(#wp-sub_prompt_content-wrap),
body.is-sub-fullscreen .field-group:has(#sub_prompt_content) {
    flex: 1 1 auto !important;
    min-height: 0 !important;
    display: flex !important;
    flex-direction: column !important;
    margin: 0 !important;
    padding: 0 20px 12px !important;
}

body.is-sub-fullscreen #wp-sub_prompt_content-wrap,
body.is-sub-fullscreen #sub_prompt_content-editor-container,
body.is-sub-fullscreen .wp-editor-container {
    flex: 1 1 auto !important;
    min-height: 0 !important;
    display: flex !important;
    flex-direction: column !important;
    height: auto !important;
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    background: transparent !important;
}

body.is-sub-fullscreen .quicktags-toolbar,
body.is-sub-fullscreen .wp-editor-tabs,
body.is-sub-fullscreen .sub-fullscreen-btn {
    display: none !important;
}

body.is-sub-fullscreen textarea#sub_prompt_content,
body.is-sub-fullscreen .wp-editor-area {
