    box-shadow: 0 -6px 24px rgba(15, 23, 42, 0.06) !important;
}

body.is-sub-fullscreen .sub-prompt-form-row .field-group-inline,
body.is-sub-fullscreen .sub-prompt-form-row .delete-persona-btn {
    display: none !important;
}

body.is-sub-fullscreen .sub-character-count {
    display: inline-flex !important;
    align-items: center !important;
    margin-left: auto !important;
    font-size: 13px !important;
    color: #64748b !important;
}

/* Estilos para os botões de tela cheia (legado — não sobrescreve a barra padronizada do prompt) */
.fullscreen-btn:not(.papo-action-btn) {
    background: var(--papo-color-primary, #007cba) !important;
    color: white !important;
    border: 1px solid var(--papo-color-primary, #007cba) !important;
    padding: 8px 12px !important;
    border-radius: 4px !important;
    cursor: pointer !important;
    font-size: 12px !important;
    font-weight: 600 !important;
    transition: all 0.3s ease !important;
    margin-left: 5px !important;
}

.fullscreen-btn:not(.papo-action-btn):hover {
    background: var(--papo-color-primary-dark, #005a87) !important;
    border-color: var(--papo-color-primary-dark, #005a87) !important;
}

.fullscreen-btn.exit {
    background: var(--papo-color-danger, #dc3545) !important;
    border-color: var(--papo-color-danger, #dc3545) !important;
}

.fullscreen-btn.exit:hover {
    background: #c82333 !important;
    border-color: #c82333 !important;
}

/* Botão X para fechar tela cheia */
.fullscreen-close-btn {
    position: fixed !important;
    top: max(12px, env(safe-area-inset-top, 0px)) !important;
    right: max(12px, env(safe-area-inset-right, 0px)) !important;
    width: 44px !important;
    height: 44px !important;
    background: rgba(15, 23, 42, 0.88) !important;
    color: white !important;
    border: none !important;
    border-radius: 10px !important;
    font-size: 24px !important;
    font-weight: 400 !important;
    line-height: 1 !important;
    z-index: 1000001 !important;
    cursor: pointer !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    transition: background 0.2s ease, transform 0.2s ease !important;
    box-shadow: 0 8px 24px rgba(15, 23, 42, 0.25) !important;
    padding: 0 !important;
    margin: 0 !important;
}

.fullscreen-close-btn:hover {
    background: rgba(15, 23, 42, 1) !important;
    transform: scale(1.04) !important;
}

.fullscreen-close-btn:active {
    transform: scale(0.95) !important;
}

/* Responsividade */
@media (max-width: 768px) {
    body.is-main-fullscreen #papo-prompt-sections {
        padding: 0 12px 12px !important;
    }

    body.is-main-fullscreen .papo-section-textarea,
    body.is-sub-fullscreen textarea#sub_prompt_content {
