/* Estilos para as caixas de entrada do Chatwoot */
.caixas-entrada-lista {
    margin-top: 0;
}

/* Grid — caixas de entrada (tokens Papo; detalhe em admin.css dentro de .caixas-entrada-lista) */
.papo-inboxes-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(148px, 1fr));
    gap: 8px;
    padding: 4px 0 2px;
}

.papo-inbox-card {
    min-width: 0;
    padding: 0.48rem 0.55rem 0.5rem;
    background: #fff;
    border: 1px solid var(--papo-color-border, #e2e8f0);
    border-radius: 8px;
    box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
    transition: border-color 0.15s ease, background 0.15s ease;
}

.papo-inbox-card:hover {
    border-color: #cbd5e1;
}

.papo-inbox-card--on {
    border-color: var(--papo-color-brand-border, #bbf7d0);
    background: var(--papo-color-brand-soft, #f0fdf4);
}

.papo-inbox-card__row--head {
    display: flex;
    align-items: center;
    gap: 0.18rem;
    margin-bottom: 0.3rem;
}

.papo-inbox-card__head-spacer {
    flex: 1 1 auto;
    min-width: 0;
}

.papo-inbox-card__drag {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    width: 0.9rem;
    height: 0.9rem;
    margin: 0;
    padding: 0;
    border: none;
    border-radius: 3px;
    background: transparent;
    color: #cbd5e1;
    cursor: grab;
    touch-action: none;
}

.papo-inbox-card__drag svg {
    display: block;
    width: 0.72rem;
    height: 0.72rem;
}

.papo-inbox-card--dragging {
    opacity: 0.65;
    box-shadow: 0 8px 22px rgba(15, 23, 42, 0.14);
}

.papo-inbox-card__id {
    margin: 0;
    padding: 0;
    border: none;
    background: transparent;
    font-size: 0.5625rem;
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #94a3b8;
    font-variant-numeric: tabular-nums;
    cursor: pointer;
    transition: color 0.15s ease;
}

.papo-inbox-card__id:hover,
