}

.papo-inbox-card--on .papo-inbox-card__name {
    color: #166534;
}

.papo-inbox-card__phone {
    display: flex;
    justify-content: center;
    margin: 0 0 0.3rem;
    min-width: 0;
}

.papo-inbox-card__phone-chip {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.22rem;
    max-width: 100%;
    min-width: 0;
    padding: 0.12rem 0.42rem;
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.055);
    border: 1px solid rgba(148, 163, 184, 0.28);
}

.papo-inbox-card__phone-icon {
    display: inline-flex;
    flex-shrink: 0;
    width: 0.5625rem;
    height: 0.5625rem;
    color: #64748b;
}

.papo-inbox-card__phone-icon svg {
    display: block;
    width: 100%;
    height: 100%;
}

.papo-inbox-card__phone-num {
    min-width: 0;
    font-size: 0.5625rem;
    font-weight: 600;
    line-height: 1.15;
    color: #475569;
    font-variant-numeric: tabular-nums;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.papo-inbox-card__note {
    display: block;
    width: 100%;
    max-width: 100%;
    box-sizing: border-box;
    margin: 0.28rem 0 0;
    padding: 0 0.28rem;
    height: 1.2rem;
    border: 1px solid transparent;
    border-radius: 4px;
    background: rgba(99, 102, 241, 0.07);
    font-size: 0.5625rem;
    font-weight: 500;
    font-style: italic;
    line-height: 1.2;
    color: #64748b;
    opacity: 0.88;
}

.papo-inbox-card__note::placeholder {
    color: #a8b3c7;
    font-weight: 400;
    font-style: italic;
}

.papo-inbox-card__note:not(:placeholder-shown) {
    opacity: 1;
    font-style: normal;
    color: #475569;
}

.papo-inbox-card__note:focus {
    outline: none;
    opacity: 1;
    font-style: normal;
    border-color: rgba(99, 102, 241, 0.35);
    background: rgba(255, 255, 255, 0.92);
    color: #334155;
    box-shadow: 0 0 0 2px rgba(99, 102, 241, 0.1);
}

.papo-inbox-card .papo-inboxes-switch.switch {
    width: 28px !important;
    height: 15px !important;
    flex-shrink: 0;
}

