    height: 9px !important;
    width: 9px !important;
    left: 3px !important;
    bottom: 3px !important;
}

.papo-inbox-card .papo-inboxes-switch input:checked + .slider:before {
    transform: translateX(13px) !important;
}

.papo-inbox-card .papo-inboxes-switch input:checked + .slider {
    background-color: var(--papo-color-brand, #61ce70) !important;
}

