/* CSS para o acordeão de ajuda do WhatsApp */
.papo-accordion-help {
    margin-bottom: 18px;
    border-radius: 8px;
    background: var(--papo-color-soft, #f8fafc);
    box-shadow: 0 1px 4px rgba(0,0,0,0.04);
    border: 1px solid #e3e7ed;
}
.papo-accordion-header {
    display: flex;
    align-items: center;
    cursor: pointer;
    padding: 13px 18px;
    font-size: 16px;
    font-weight: 600;
    color: #2d3748;
    border-radius: 8px 8px 0 0;
    background: #e9f5ff;
    transition: background 0.2s;
}
.papo-accordion-header:hover {
    background: #d2eaff;
}
.papo-accordion-header i {
    margin-right: 10px;
    color: var(--papo-color-primary, #007cba);
    font-size: 20px;
}
.papo-accordion-content {
    display: none;
    padding: 0 18px 18px 18px;
    border-top: 1px solid #e3e7ed;
    background: var(--papo-color-soft, #f8fafc);
    border-radius: 0 0 8px 8px;
}
.papo-accordion-content.open {
    display: flex;
    gap: 32px;
    flex-wrap: wrap;
}
.papo-accordion-col-left {
    flex: 1 1 220px;
    min-width: 220px;
    max-width: 350px;
    padding: 18px 0 0 0;
}
.papo-accordion-col-right {
    flex: 1 1 320px;
    min-width: 280px;
    max-width: 480px;
    padding: 18px 0 0 0;
    display: flex;
    align-items: flex-start;
    justify-content: center;
}
.papo-accordion-help ul {
    margin: 0 0 0 18px;
    padding: 0;
    list-style: disc inside;
    color: #2d3748;
    font-size: 15px;
}
.papo-accordion-help li {
    margin-bottom: 10px;
}
.papo-accordion-help .papo-tip-title {
    font-weight: bold;
    color: var(--papo-color-primary, #007cba);
    margin-bottom: 7px;
    font-size: 15px;
}
.papo-accordion-help iframe {
    border-radius: 8px;
    border: 1px solid #e3e7ed;
