    .papo-accordion-col-right, .papo-accordion-col-left { max-width: 100%; }
}

/* Tutoriais em vídeo: ícone à direita no fluxo da página (não sobrepõe a viewport inteira) */
.papo-tutorial-fab {
    position: relative;
    width: 100%;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    box-sizing: border-box;
    margin: 10px 0 20px;
    font-family: inherit;
    isolation: isolate;
}

/* Fim da página / último shortcode do painel */
.papo-tutorial-fab--page-end,
.papo-painel-tutorial-tail .papo-tutorial-fab {
    margin-top: 28px;
    margin-bottom: 8px;
    padding-top: 20px;
    border-top: 1px solid #e8e8e8;
}

.papo-painel-tutorial-tail {
    width: 100%;
}

.papo-tutorial-fab--page-end .papo-tutorial-fab__panel {
    top: auto;
    bottom: calc(100% + 10px);
    transform: translateY(6px);
}

.papo-tutorial-fab--page-end.is-open .papo-tutorial-fab__panel {
    transform: translateY(0);
}
.papo-tutorial-fab.is-open {
    z-index: 30;
}

.papo-tutorial-fab__trigger {
    flex-shrink: 0;
    width: 52px;
    height: 52px;
    border-radius: 50%;
    border: none;
    padding: 0;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(160deg, #0ea5e9 0%, #0369a1 100%);
    color: #fff;
    box-shadow: 0 4px 16px rgba(3, 105, 161, 0.32);
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.papo-tutorial-fab__trigger:hover {
    transform: translateY(-1px);
    box-shadow: 0 8px 22px rgba(3, 105, 161, 0.42);
}
.papo-tutorial-fab__trigger:focus-visible {
    outline: 3px solid #7dd3fc;
    outline-offset: 3px;
}
.papo-tutorial-fab.is-open .papo-tutorial-fab__trigger {
    background: linear-gradient(160deg, #0284c7 0%, #075985 100%);
}
.papo-tutorial-fab__trigger-mark {
    font-size: 1.62rem;
    font-weight: 700;
    line-height: 1;
}

.papo-tutorial-fab__panel {
    position: absolute;
    top: calc(100% + 10px);
    right: 0;
    z-index: 31;
    width: min(440px, 100%);
    max-height: min(78vh, 580px);
    display: flex;
    flex-direction: column;
    border-radius: 14px;
    background: #fff;
    box-shadow: 0 16px 40px rgba(15, 23, 42, 0.16);
    border: 1px solid rgba(226, 232, 240, 0.96);
    overflow: hidden;
    opacity: 0;
    visibility: hidden;
    transform: translateY(-6px);
    pointer-events: none;
    transition: opacity 0.2s ease, visibility 0.2s ease, transform 0.2s ease;
}
.papo-tutorial-fab.is-open .papo-tutorial-fab__panel {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
    pointer-events: auto;
}

.papo-tutorial-fab__panel-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 12px;
    padding: 14px 16px;
    border-bottom: 1px solid var(--papo-color-border, #e2e8f0);
    background: linear-gradient(180deg, var(--papo-color-soft, #f8fafc) 0%, #f1f5f9 100%);
}
.papo-tutorial-fab__panel-title {
    font-size: 15px;
    font-weight: 700;
    color: #0f172a;
    line-height: 1.35;
}
.papo-tutorial-fab__close {
    flex-shrink: 0;
    border: none;
    background: transparent;
    color: var(--papo-color-muted, #64748b);
    font-size: 1.5rem;
    line-height: 1;
    cursor: pointer;
    padding: 2px 8px;
    border-radius: 8px;
    margin: -4px -6px 0 0;
}
.papo-tutorial-fab__close:hover {
    background: var(--papo-color-border, #e2e8f0);
    color: #0f172a;
}
.papo-tutorial-fab__close:focus-visible {
    outline: 2px solid #0ea5e9;
    outline-offset: 2px;
}

.papo-tutorial-fab__panel-scroll {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    padding: 16px 18px 20px;
    background: #fff;
}

.papo-tutorial-fab-body-cols {
    display: flex;
    flex-wrap: wrap;
    gap: 20px 28px;
}
.papo-tutorial-fab-body-cols .papo-accordion-col-left {
    flex: 1 1 220px;
    min-width: 200px;
    max-width: 100%;
    padding: 0;
}
.papo-tutorial-fab-body-cols .papo-accordion-col-right {
    flex: 1 1 280px;
    min-width: 240px;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    padding: 0;
}
.papo-tutorial-fab-body-cols iframe {
    border-radius: 10px;
    border: 1px solid var(--papo-color-border, #e2e8f0);
    width: 100%;
    max-width: 420px;
    min-height: 200px;
    aspect-ratio: 16/9;
    background: #000;
}
@media (max-width: 900px) {
    .papo-tutorial-fab-body-cols .papo-accordion-col-right,
    .papo-tutorial-fab-body-cols .papo-accordion-col-left {
        max-width: 100%;
    }
    .papo-tutorial-fab__panel {
        width: 100%;
        max-height: min(75vh, 560px);
    }
}

