    border: 1px solid #cfcfcf;
    border-radius: 8px;
    color: #222;
    cursor: pointer;
    font-size: 13px;
    font-weight: 600;
    padding: 10px 20px;
    width: 100%;
    transition: background 0.15s ease, border-color 0.15s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.papo-users-btn:hover {
    background: #e5e5e5;
    border-color: #b8b8b8;
}

.papo-users-btn:disabled {
    opacity: 0.65;
    cursor: not-allowed;
}

.papo-users-spinner {
    display: inline-block;
    width: 14px;
    height: 14px;
    border: 2px solid rgba(0, 0, 0, 0.08);
    border-top-color: #555;
    border-radius: 50%;
    animation: papo-users-spin 0.7s linear infinite;
    vertical-align: middle;
}

@keyframes papo-users-spin {
    to { transform: rotate(360deg); }
}

.papo-users-message {
    border-radius: 6px;
    font-size: 13px;
    padding: 10px 12px;
    text-align: center;
    margin-top: 12px;
    border: 1px solid #dcdcdc;
}

.papo-users-success {
    background: #f2f2f2;
    color: #1f1f1f;
}

.papo-users-error {
    background: #efefef;
    color: #1f1f1f;
    border-color: #bdbdbd;
}

.papo-users-info {
    background: #f7f7f7;
    color: #333;
}

.papo-users-error-box {
    color: #444;
    font-size: 13px;
}

div.papo-users-error:not(#papo-users-message) {
    padding: 12px 14px;
    border-radius: 6px;
    font-size: 13px;
    background-color: #f2f2f2;
    color: #1f1f1f;
    border: 1px solid #bdbdbd;
    margin: 12px 0;
}

@media (max-width: 480px) {
    .papo-users-container {
        padding: 16px;
    }

    .papo-users-header {
        flex-direction: column;
        align-items: flex-start;
    }

    .papo-users-current {
        text-align: left;
    }
}

/* Minha conta > Assinaturas — uso de usuários Papo */
.papo-subscription-users-notice {
    margin: 0 0 1.25em;
}

.papo-subscription-users-notice__line {
    margin: 0 0 0.5em;
}

.papo-subscription-users-notice__line:last-child {
    margin-bottom: 0;
    font-size: 0.92em;
    opacity: 0.85;
}

