@media only screen and ( max-width: 768px ) {
	.subscription_details .button {
		margin-bottom: 2px;
		width: 100%;
		max-width: 200px;
		text-align: center;
	}
}

.subscription-auto-renew-toggle {
	margin-left: 5px;
	margin-bottom: 2px;
	position: relative;
	top: 4px;
}

.subscription-auto-renew-toggle__i {
	height: 20px;
	width: 32px;
	border: 2px solid #00ba8a;
	background-color: #00ba8a;
	display: inline-block;
	text-indent: -9999px;
	border-radius: 10em;
	position: relative;
	margin-top: -1px;
	vertical-align: text-top;
}

.subscription-auto-renew-toggle__i::before {
	content: '';
	display: block;
	width: 16px;
	height: 16px;
	background: #fff;
	position: absolute;
	top: 0;
	right: 0;
	border-radius: 100%;
}

.subscription-auto-renew-toggle--off .subscription-auto-renew-toggle__i {
	border-color: #999;
	background-color: #999;
}

.subscription-auto-renew-toggle--off
	.subscription-auto-renew-toggle__i::before {
	right: auto;
	left: 0;
}

.subscription-auto-renew-toggle--loading .subscription-auto-renew-toggle__i {
	opacity: 0.5;
}

.subscription-auto-renew-toggle--hidden {
	display: none;
}
.subscription-auto-renew-toggle-disabled-note {
	margin-left: 1em;
}

/**
 * Early renewal Modal
**/
.wcs_early_renew_modal_totals_table {
	overflow: scroll;
	height: 80%;
	margin-bottom: 1em;
}

.wcs_early_renew_modal_note {
	position: sticky;
	bottom: 0;
	min-width: 100%;
	width: 0;
}

#early_renewal_modal_submit {
	width: 100%;
	font-size: 1.4em;
	text-align: center;
}


