/* Papo toast — feedback flutuante no canto superior direito */

.papo-toast-root {
    position: fixed;
    top: max(1rem, env(safe-area-inset-top, 0px));
    right: max(1rem, env(safe-area-inset-right, 0px));
    z-index: 1000002;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0.5rem;
    width: min(22rem, calc(100vw - 2rem));
    pointer-events: none;
}

.papo-toast {
    display: flex;
    align-items: flex-start;
    gap: 0.625rem;
    width: 100%;
    padding: 0.75rem 0.875rem;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.94);
    border: 1px solid var(--papo-color-border, #e2e8f0);
    box-shadow:
        0 16px 40px -12px rgba(15, 23, 42, 0.22),
        0 4px 12px -4px rgba(15, 23, 42, 0.08);
    backdrop-filter: blur(14px) saturate(150%);
    -webkit-backdrop-filter: blur(14px) saturate(150%);
    color: var(--papo-color-text, #0f172a);
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    font-size: 0.8125rem;
    line-height: 1.45;
    pointer-events: auto;
    transform: translateX(calc(100% + 1.5rem));
    opacity: 0;
    transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.28s ease;
}

.papo-toast.is-visible {
    transform: translateX(0);
    opacity: 1;
}

.papo-toast.is-leaving {
    transform: translateX(calc(100% + 1.5rem));
    opacity: 0;
}

.papo-toast__icon {
    flex-shrink: 0;
    width: 1.375rem;
    height: 1.375rem;
    margin-top: 0.05rem;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    font-weight: 700;
    line-height: 1;
}

.papo-toast__body {
    flex: 1;
    min-width: 0;
    padding-right: 0.25rem;
}

.papo-toast__message {
    margin: 0;
    word-break: break-word;
}

.papo-toast__close {
    flex-shrink: 0;
    width: 1.5rem;
    height: 1.5rem;
    margin: -0.125rem -0.125rem 0 0;
    padding: 0;
    border: none;
    border-radius: 8px;
    background: transparent;
    color: var(--papo-color-muted, #64748b);
    cursor: pointer;
    font-size: 1rem;
    line-height: 1;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: background 0.15s ease, color 0.15s ease;
}

.papo-toast__close:hover {
    background: rgba(15, 23, 42, 0.06);
    color: var(--papo-color-text, #0f172a);
}

.papo-toast__close:focus-visible {
    outline: 2px solid var(--papo-color-brand, #61ce70);
    outline-offset: 2px;
}

.papo-toast--success {
    border-left: 3px solid var(--papo-color-brand, #61ce70);
}

.papo-toast--success .papo-toast__icon {
    background: var(--papo-color-brand-soft, #f0fdf4);
    color: var(--papo-color-brand-dark, #28a745);
}

.papo-toast--error {
    border-left: 3px solid var(--papo-color-danger, #dc3545);
}

.papo-toast--error .papo-toast__icon {
    background: #fef2f2;
    color: var(--papo-color-danger, #dc3545);
}

.papo-toast--warning {
    border-left: 3px solid #f59e0b;
}

.papo-toast--warning .papo-toast__icon {
    background: #fffbeb;
    color: #d97706;
}

.papo-toast--info {
    border-left: 3px solid var(--papo-color-primary, #007cba);
}

.papo-toast--info .papo-toast__icon {
    background: #eff6ff;
    color: var(--papo-color-primary, #007cba);
}

@media (max-width: 768px) {
    .papo-toast-root {
        top: max(0.75rem, env(safe-area-inset-top, 0px));
        right: max(0.75rem, env(safe-area-inset-right, 0px));
        width: min(20rem, calc(100vw - 1.5rem));
    }

    .papo-toast {
        padding: 0.6875rem 0.75rem;
        font-size: 0.78125rem;
    }
}

/* Modal Google Calendar - Estilo Appel */
.google-calendar-modal {
    display: none;
    position: fixed;
    z-index: 999999;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0, 0, 0, 0.5);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
}

.google-calendar-modal-content {
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    margin: 5% auto;
    padding: 0;
    border-radius: 20px;
    width: 90%;
    max-width: 600px;
    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.25);
    border: 1px solid rgba(255, 255, 255, 0.2);
    overflow: hidden;
    animation: modalSlideIn 0.3s ease-out;
}

@keyframes modalSlideIn {
    from {
        opacity: 0;
        transform: translateY(-30px) scale(0.95);
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

.google-calendar-modal-header {
    background: linear-gradient(135deg, #4285f4 0%, #34a853 100%);
    color: white;
    padding: 25px 30px;
    position: relative;
}

.google-calendar-modal-header h3 {
    margin: 0;
    font-size: 24px;
    font-weight: 600;
    text-align: center;
}

.google-calendar-modal-close {
    position: absolute;
    right: 20px;
    top: 50%;
    transform: translateY(-50%);
    background: rgba(255, 255, 255, 0.2);
    border: none;
    color: white;
    font-size: 28px;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}

.google-calendar-modal-close:hover {
    background: rgba(255, 255, 255, 0.3);
    transform: translateY(-50%) scale(1.1);
}

.google-calendar-modal-body {
    padding: 30px;
    max-height: 70vh;
    overflow-y: auto;
}

/* Status da conexão */
.connection-status {
    display: flex;
    align-items: center;
    gap: 15px;
    padding: 20px;
    background: rgba(66, 133, 244, 0.1);
    border-radius: 15px;
    margin-bottom: 25px;
    border: 1px solid rgba(66, 133, 244, 0.2);
}

.status-indicator {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: #ccc;
    transition: all 0.3s ease;
}

.status-indicator.connected {
    background: #34a853;
    box-shadow: 0 0 10px rgba(52, 168, 83, 0.5);
}

.status-indicator.disconnected {
    background: #ea4335;
    box-shadow: 0 0 10px rgba(234, 67, 53, 0.5);
}

#status-text {
    font-weight: 500;
    color: #333;
}

/* Seções do modal */
.credentials-section,
.connect-section,
.calendars-section,
.disconnect-section {
    margin-bottom: 25px;
}

/* Grupos de formulário */
.form-group {
    margin-bottom: 20px;
}

.form-group label {
    display: block;
    margin-bottom: 8px;
    font-weight: 600;
    color: #333;
    font-size: 14px;
}

.form-group input {
    width: 100%;
    padding: 12px 15px;
    border: 2px solid #e1e5e9;
    border-radius: 10px;
    font-size: 14px;
    transition: all 0.3s ease;
    background: white;
}

.form-group input:focus {
    outline: none;
    border-color: #4285f4;
    box-shadow: 0 0 0 3px rgba(66, 133, 244, 0.1);
}

.form-group small {
    display: block;
    margin-top: 5px;
    color: #666;
    font-size: 12px;
}

.form-group small a {
    color: #4285f4;
    text-decoration: none;
}

.form-group small a:hover {
    text-decoration: underline;
}

/* Botões */
.button {
    padding: 12px 24px;
    border: none;
    border-radius: 10px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    text-decoration: none;
    display: inline-flex;
    align-items: center;
    gap: 8px;
}

.button-primary {
    background: linear-gradient(135deg, #4285f4 0%, #34a853 100%);
    color: white;
    box-shadow: 0 4px 15px rgba(66, 133, 244, 0.3);
}

.button-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(66, 133, 244, 0.4);
}

.button-secondary {
    background: #f8f9fa;
    color: #333;
    border: 2px solid #e1e5e9;
}

.button-secondary:hover {
    background: #e9ecef;
    border-color: #adb5bd;
}

.button-danger {
    background: linear-gradient(135deg, #ea4335 0%, var(--papo-color-danger, #dc3545) 100%);
    color: white;
    box-shadow: 0 4px 15px rgba(234, 67, 53, 0.3);
}

.button-danger:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(234, 67, 53, 0.4);
}

.button-small {
    padding: 8px 16px;
    font-size: 12px;
}

/* Botão de conexão Google */
.google-connect-btn {
    width: 100%;
    justify-content: center;
    padding: 15px 24px;
    font-size: 16px;
    background: linear-gradient(135deg, #4285f4 0%, #34a853 100%);
    border: none;
    border-radius: 12px;
    color: white;
    font-weight: 600;
    box-shadow: 0 4px 15px rgba(66, 133, 244, 0.3);
    transition: all 0.3s ease;
}

.google-connect-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(66, 133, 244, 0.4);
}

.google-connect-btn img {
    border-radius: 4px;
}

/* Lista de calendários */
.calendars-section h4 {
    margin: 0 0 20px 0;
    color: #333;
    font-size: 18px;
    font-weight: 600;
}

.calendar-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 15px;
    background: #f8f9fa;
    border-radius: 10px;
    margin-bottom: 10px;
    border: 1px solid #e1e5e9;
    transition: all 0.3s ease;
}

.calendar-item:hover {
    background: #e9ecef;
    transform: translateX(5px);
}

.calendar-info {
    flex: 1;
}

.calendar-info strong {
    display: block;
    color: #333;
    font-size: 14px;
    margin-bottom: 3px;
}

.calendar-info small {
    color: #666;
    font-size: 12px;
    font-family: monospace;
}

.calendar-actions {
    margin-left: 15px;
}

/* ── Google Calendar inline (painel Conexões) ── */
.papo-gcal {
    padding: 0;
}

.papo-gcal-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 0.5rem;
}

