        font-size: 0.5rem;
        font-weight: 600;
        line-height: 1.1;
        white-space: normal;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
        overflow: hidden;
        word-break: break-word;
    }

    .papo-account-nav__foot {
        padding: 0.25rem 0.5rem 0.375rem;
    }

    .papo-account-nav__profile-card {
        padding: 0.25rem 0.375rem;
        border-radius: 10px;
    }

    .papo-account-nav__profile-body {
        gap: 0.3125rem;
        align-items: center;
    }

    .papo-account-nav__profile-avatar {
        width: 1.375rem;
        height: 1.375rem;
    }

    /* Uma linha: avatar · nome · status · stats · sair */
    .papo-account-nav__profile-content {
        flex-direction: row;
        flex-wrap: nowrap;
        align-items: center;
        gap: 0.3125rem;
        overflow: hidden;
    }

    .papo-account-nav__profile-head {
        display: contents;
    }

    .papo-account-nav__profile-name {
        order: 1;
        flex: 0 1 auto;
        min-width: 0;
        max-width: 5.5rem;
        font-size: 0.5625rem;
        font-weight: 700;
    }

    .papo-account-nav__profile-sub {
        order: 2;
        flex: 0 0 auto;
        margin-top: 0;
        gap: 0;
    }

    .papo-account-nav__profile-sub-label {
        display: none;
    }

    .papo-account-nav__profile-sub-dot {
        width: 0.3125rem;
        height: 0.3125rem;
    }

    .papo-account-nav__profile-stats {
        order: 3;
        flex: 1 1 auto;
        min-width: 0;
        gap: 0.125rem;
        justify-content: flex-end;
    }

    .papo-account-nav__profile-stat {
        font-size: 0.5rem;
        gap: 0.0625rem;
    }

    .papo-account-nav__profile-stat-icon {
        width: 0.5rem;
        height: 0.5rem;
    }

    .papo-account-nav__profile-stat-sep {
        font-size: 0.4375rem;
    }

    .papo-account-nav__profile-logout {
        order: 4;
        flex: 0 0 auto;
        width: 1.125rem;
        height: 1.125rem;
        margin-left: 0.0625rem;
        border-radius: 5px;
    }

    .papo-account-nav__profile-logout svg {
        width: 0.625rem;
        height: 0.625rem;
    }

    /* Sheet "Mais" — menu overflow mobile */
    .papo-account-mobile-sheet {
        position: fixed;
        inset: 0;
        z-index: 100030;
        display: flex;
        align-items: flex-end;
        justify-content: center;
    }

    .papo-account-mobile-sheet[hidden] {
        display: none !important;
    }

    .papo-account-mobile-sheet__backdrop {
        position: absolute;
        inset: 0;
        background: rgba(15, 23, 42, 0.28);
        backdrop-filter: blur(2px);
        -webkit-backdrop-filter: blur(2px);
    }

    .papo-account-mobile-sheet__panel {
        position: relative;
        z-index: 1;
        width: 100%;
        max-width: 32rem;
        max-height: min(58dvh, 24rem);
        display: flex;
        flex-direction: column;
        padding: 0.75rem 1rem max(1rem, env(safe-area-inset-bottom, 0px));
        border: 1px solid rgba(255, 255, 255, 0.65);
        border-bottom: none;
        border-radius: 18px 18px 0 0;
        background: rgba(255, 255, 255, 0.78);
        backdrop-filter: blur(20px) saturate(140%);
        -webkit-backdrop-filter: blur(20px) saturate(140%);
        box-shadow:
            0 -12px 40px rgba(15, 23, 42, 0.12),
            inset 0 1px 0 rgba(255, 255, 255, 0.9);
    }

    .papo-account-mobile-sheet__handle {
        width: 2.5rem;
        height: 0.25rem;
        margin: 0 auto 0.75rem;
        border-radius: 999px;
        background: var(--papo-ac-border);
    }

    .papo-account-mobile-sheet__header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
        margin-bottom: 0.625rem;
    }

    .papo-account-mobile-sheet__title {
        margin: 0;
        font-size: 0.875rem;
        font-weight: 700;
        color: var(--papo-ac-text);
    }

    .papo-account-mobile-sheet__close {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 2rem;
        height: 2rem;
        padding: 0;
        border: none;
        border-radius: 8px;
        background: transparent;
        color: var(--papo-ac-muted);
        cursor: pointer;
    }

    .papo-account-mobile-sheet__close:hover {
        background: var(--papo-ac-soft);
        color: var(--papo-ac-text);
    }

    .papo-account-mobile-sheet__close svg {
        width: 1rem;
        height: 1rem;
    }

    .papo-account-mobile-sheet__list {
        list-style: none;
        margin: 0;
        padding: 0;
        display: grid;
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 0.375rem 0.25rem;
        overflow-y: auto;
        flex: 1 1 auto;
        min-height: 0;
    }

    .papo-account-mobile-sheet__item {
        margin: 0;
        min-width: 0;
    }

    .papo-account-mobile-sheet__link {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: flex-start;
        gap: 0.25rem;
        width: 100%;
        min-height: 3.75rem;
        padding: 0.4375rem 0.1875rem;
        border-radius: 12px;
        text-decoration: none !important;
        color: var(--papo-ac-text) !important;
        font-size: 0.5625rem;
        font-weight: 600;
        text-align: center;
