    }

    .papo-account-mobile-sheet__link:hover {
        background: var(--papo-ac-soft);
    }

    .papo-account-mobile-sheet__item.is-active .papo-account-mobile-sheet__link {
        background: var(--papo-ac-brand-soft);
        color: var(--papo-ac-brand-dark) !important;
    }

    .papo-account-mobile-sheet__link .papo-account-nav__icon {
        flex-shrink: 0;
        width: 1.875rem;
        height: 1.875rem;
    }

    .papo-account-mobile-sheet__link .papo-account-nav__text {
        font-size: 0.5625rem;
        font-weight: 600;
        line-height: 1.15;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
        overflow: hidden;
        word-break: break-word;
    }

    .papo-account-mobile-sheet__extras {
        margin-top: 0.625rem;
        padding-top: 0.625rem;
        border-top: 1px solid var(--papo-ac-border);
    }

    .papo-account-mobile-sheet__extras .papo-account-nav__utility {
        display: flex !important;
        flex-direction: column;
        align-items: center;
        gap: 0.3125rem;
        padding: 0;
    }

    .papo-account-mobile-sheet__extras .papo-account-nav__utility-links {
        justify-content: center;
        gap: 0.25rem;
    }

    html.papo-account-mobile-sheet-open,
    body.papo-account-mobile-sheet-open {
        overflow: hidden;
    }
}

@media (max-width: 480px) {
    .papo-account-shell__sidebar > .papo-account-nav .papo-account-nav__link {
        min-height: 2.875rem;
