    }

    .papo-account-nav__text {
        font-size: 0.46875rem;
    }

    .papo-account-mobile-sheet__list {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }

    .papo-account-nav__profile-name {
        max-width: 4rem;
    }

    .papo-account-nav__profile-stat--balance .papo-account-nav__profile-stat-value {
        max-width: 3.25rem;
    }
}

/* Página inicial — boas-vindas Minha Conta */
.papo-account-welcome {
    max-width: 920px;
    animation: papo-welcome-fade-in 0.55s ease-out both;
}

@keyframes papo-welcome-fade-in {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.papo-account-welcome__hero {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 1.25rem 1.5rem;
    align-items: center;
    padding: 1.25rem 1.375rem;
    margin-bottom: 1rem;
    border: 1px solid var(--papo-ac-border, #e2e8f0);
    border-radius: 14px;
    background:
        radial-gradient(120% 120% at 100% 0%, color-mix(in srgb, var(--papo-ac-brand, #2563eb) 14%, transparent), transparent 55%),
        linear-gradient(180deg, #fff 0%, var(--papo-ac-soft, #f8fafc) 100%);
}

.papo-account-welcome__orb {
    position: relative;
    width: 4.5rem;
    height: 4.5rem;
    flex-shrink: 0;
}

.papo-account-welcome__orb-ring {
    position: absolute;
    inset: 0;
    border-radius: 50%;
    border: 2px solid color-mix(in srgb, var(--papo-ac-brand, #2563eb) 35%, transparent);
    animation: papo-welcome-pulse 2.4s ease-in-out infinite;
}

.papo-account-welcome__orb-core {
    position: absolute;
    inset: 0.625rem;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 50%;
    color: #fff;
    background: linear-gradient(135deg, var(--papo-ac-brand, #2563eb), color-mix(in srgb, var(--papo-ac-brand, #2563eb) 70%, #7c3aed));
    box-shadow: 0 10px 24px color-mix(in srgb, var(--papo-ac-brand, #2563eb) 28%, transparent);
    animation: papo-welcome-float 3s ease-in-out infinite;
}

.papo-account-welcome__orb-core svg {
    width: 1.375rem;
    height: 1.375rem;
}

@keyframes papo-welcome-pulse {
    0%, 100% { transform: scale(1); opacity: 0.85; }
    50% { transform: scale(1.08); opacity: 0.45; }
}

@keyframes papo-welcome-float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-3px); }
}

.papo-account-welcome__eyebrow {
    margin: 0 0 0.25rem;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--papo-ac-brand, #2563eb);
}

.papo-account-welcome__title {
    margin: 0 0 0.5rem;
    font-size: 1.375rem;
    font-weight: 800;
    line-height: 1.2;
    color: var(--papo-ac-text, #0f172a);
}

.papo-account-welcome__lead {
    margin: 0;
    font-size: 0.9375rem;
    line-height: 1.55;
    color: var(--papo-ac-muted, #64748b);
    max-width: 42rem;
}

.papo-account-welcome__typewriter {
    animation: papo-welcome-fade-in 0.8s ease-out 0.15s both;
}

.papo-account-welcome__grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.875rem;
}

/* --- Cards ---- */

.papo-account-welcome__card {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    padding: 1.25rem 1.125rem 1.125rem;
    border: 1px solid var(--papo-ac-border, #e2e8f0);
    border-radius: 14px;
    background: #fff;
    text-decoration: none !important;
    transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
}

.papo-account-welcome__card:hover {
    border-color: color-mix(in srgb, var(--papo-ac-brand, #2563eb) 40%, #cbd5e1);
    box-shadow: 0 6px 20px rgba(15, 23, 42, 0.08);
    transform: translateY(-2px);
}

.papo-account-welcome__card-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 2.75rem;
    height: 2.75rem;
    margin-bottom: 0.875rem;
    border-radius: 12px;
    color: #fff;
    background: linear-gradient(135deg, var(--papo-ac-brand, #2563eb), color-mix(in srgb, var(--papo-ac-brand, #2563eb) 70%, #7c3aed));
    box-shadow: 0 4px 12px color-mix(in srgb, var(--papo-ac-brand, #2563eb) 22%, transparent);
}

.papo-account-welcome__card-icon svg {
    width: 1.25rem;
    height: 1.25rem;
}

.papo-account-welcome__card--whatsapp .papo-account-welcome__card-icon {
    background: linear-gradient(135deg, #25d366, #128c48);
    box-shadow: 0 4px 12px rgba(37, 211, 102, 0.25);
}

.papo-account-welcome__card--crm .papo-account-welcome__card-icon {
    background: linear-gradient(135deg, #7c3aed, #5b21b6);
    box-shadow: 0 4px 12px rgba(124, 58, 237, 0.25);
}

.papo-account-welcome__card-title {
    display: block;
    margin-bottom: 0.25rem;
    font-size: 0.9375rem;
    font-weight: 700;
    line-height: 1.3;
    color: var(--papo-ac-text, #0f172a);
}

.papo-account-welcome__card-desc {
    display: block;
    flex: 1;
    font-size: 0.8125rem;
    line-height: 1.45;
    color: var(--papo-ac-muted, #64748b);
}

.papo-account-welcome__card-cta {
    display: inline-flex;
    align-items: center;
    gap: 0.375rem;
    margin-top: 1rem;
    font-size: 0.8125rem;
    font-weight: 700;
    color: var(--papo-ac-brand, #2563eb);
    transition: gap 0.15s ease;
}

.papo-account-welcome__card:hover .papo-account-welcome__card-cta {
    gap: 0.5rem;
}

.papo-account-welcome__card--whatsapp .papo-account-welcome__card-cta {
    color: #128c48;
}

.papo-account-welcome__card--crm .papo-account-welcome__card-cta {
    color: #6d28d9;
}

.papo-account-welcome__external {
    margin-left: 0.2rem;
    font-size: 0.75rem;
    opacity: 0.7;
}

.papo-account-welcome__alt {
    margin: 0.75rem 0 0;
    font-size: 0.8125rem;
    color: var(--papo-ac-muted, #64748b);
    text-align: center;
}

.papo-account-welcome__alt a {
    color: var(--papo-ac-brand, #2563eb);
    font-weight: 600;
    text-decoration: none;
}

.papo-account-welcome__alt a:hover {
    text-decoration: underline;
}

/* --- Responsive --- */

@media (max-width: 768px) {
    .papo-account-welcome__hero {
        grid-template-columns: 1fr;
        text-align: center;
    }

    .papo-account-welcome__orb {
        margin: 0 auto;
    }

    .papo-account-welcome__grid {
        grid-template-columns: 1fr;
    }
}

@media (min-width: 769px) and (max-width: 960px) {
    .papo-account-welcome__grid {
        grid-template-columns: 1fr 1fr;
    }
}

body.papo-account-tutorial-open {
    overflow: hidden;
}

.papo-account-tutorial {
    position: fixed;
    inset: 0;
    z-index: 100050;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: clamp(0.75rem, 2vw, 1.25rem);
    box-sizing: border-box;
}

.papo-account-tutorial[hidden] {
    display: none !important;
}

.papo-account-tutorial__backdrop {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.48);
    backdrop-filter: blur(3px);
    -webkit-backdrop-filter: blur(3px);
    cursor: pointer;
}

.papo-account-tutorial__dialog {
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    width: min(960px, 100%);
