}

@keyframes papo-account-tutorial-in {
    from {
        opacity: 0;
        transform: translateY(10px) scale(0.985);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

.papo-account-tutorial__head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.75rem;
    padding: 0.875rem 1rem 0.875rem 1.125rem;
    border-bottom: 1px solid var(--papo-ac-border, #e2e8f0);
    background: linear-gradient(
        180deg,
        var(--papo-ac-brand-soft, #f0fdf4) 0%,
        #fff 100%
    );
    border-left: 4px solid var(--papo-ac-brand, #61ce70);
}

.papo-account-tutorial__head-copy {
    min-width: 0;
}

.papo-account-tutorial__eyebrow {
    margin: 0 0 0.2rem;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--papo-ac-brand-dark, #28a745);
