}

.papo-affiliate-area #affwp-affiliate-dashboard-tabs li {
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
}

.papo-affiliate-area #affwp-affiliate-dashboard-tabs li a {
    display: inline-flex;
    align-items: center;
    padding: 0.55rem 0.9rem;
    border-radius: 10px 10px 0 0;
    color: var(--papo-ac-muted, #64748b);
    text-decoration: none !important;
    font-size: 0.8125rem;
    font-weight: 600;
    transition: color 0.15s ease, background 0.15s ease;
}

.papo-affiliate-area #affwp-affiliate-dashboard-tabs li a:hover {
    color: var(--papo-ac-text, #1e293b);
    background: var(--papo-ac-soft, #f8fafc);
}

.papo-affiliate-area #affwp-affiliate-dashboard-tabs li.active a {
