/* Sidebar — CTA modo avançado (base da coluna esquerda) */
.papo-account-nav__advanced-cta {
    flex-shrink: 0;
    padding: 0.4375rem 0.5rem 0.3125rem;
    border-bottom: 1px solid var(--papo-ac-border, #e2e8f0);
    background: transparent;
}

.papo-account-nav__advanced-cta-link {
    display: flex;
    align-items: flex-start;
    gap: 0.4375rem;
    width: 100%;
    min-width: 0;
    padding: 0.4375rem 0.4375rem 0.4375rem 0.375rem;
    text-decoration: none !important;
    color: inherit;
    border: 1px solid color-mix(in srgb, var(--papo-ac-brand, #2563eb) 22%, var(--papo-ac-border, #e2e8f0));
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.88);
    box-shadow: none;
    transition: border-color 0.15s ease;
    box-sizing: border-box;
}

.papo-account-nav__advanced-cta-link:hover,
.papo-account-nav__advanced-cta-link:focus {
    border-color: color-mix(in srgb, var(--papo-ac-brand, #2563eb) 45%, var(--papo-ac-border, #e2e8f0));
    box-shadow: none;
    outline: none;
}

.papo-account-nav__advanced-cta-icon {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 1.625rem;
    height: 1.625rem;
    margin-top: 0.0625rem;
    border-radius: 8px;
    color: var(--papo-ac-brand, #2563eb);
    background: color-mix(in srgb, var(--papo-ac-brand, #2563eb) 12%, #fff);
    border: 1px solid color-mix(in srgb, var(--papo-ac-brand, #2563eb) 18%, transparent);
}

.papo-account-nav__advanced-cta-icon svg {
    width: 0.8125rem;
    height: 0.8125rem;
}

.papo-account-nav__advanced-cta-body {
    flex: 1 1 auto;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 0.125rem;
}

.papo-account-nav__advanced-cta-kicker {
    display: block;
    font-size: 0.5rem;
    font-weight: 700;
    line-height: 1.15;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--papo-ac-brand, #2563eb);
}

.papo-account-nav__advanced-cta-text {
    display: block;
    font-size: 0.625rem;
    font-weight: 600;
    line-height: 1.3;
    color: var(--papo-ac-text, #0f172a);
}

.papo-account-nav__advanced-cta-arrow {
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 1rem;
    height: 1rem;
    margin-top: 0.1875rem;
    color: var(--papo-ac-muted, #64748b);
    opacity: 0.85;
}

.papo-account-nav__advanced-cta-arrow svg {
    width: 0.75rem;
    height: 0.75rem;
}

body.papo-account-sidebar-collapsed .papo-account-nav__advanced-cta {
    padding-left: 0.375rem;
    padding-right: 0.375rem;
}

body.papo-account-sidebar-collapsed .papo-account-nav__advanced-cta-link {
    justify-content: center;
    padding: 0.4375rem 0.3125rem;
}

body.papo-account-sidebar-collapsed .papo-account-nav__advanced-cta-body,
body.papo-account-sidebar-collapsed .papo-account-nav__advanced-cta-arrow {
    display: none;
}

body.papo-account-sidebar-collapsed .papo-account-nav__advanced-cta-icon {
    margin-top: 0;
}

@media (max-width: 960px) {
    body.papo-account-mobile-dock .papo-account-nav__advanced-cta {
        display: none;
    }
}

/* Balão — Full chat / CRM completo (sidebar + mobile dock) */
.papo-account-nav__item--chat-completo.papo-nav-crm-hint-active {
    position: relative;
    z-index: 25;
}

.papo-account-nav__item--chat-completo.papo-nav-crm-hint-active > .papo-account-nav__link {
    position: relative;
    z-index: 1;
    outline: 2px solid rgba(37, 99, 235, 0.5);
    outline-offset: 1px;
    border-radius: 10px;
    animation: papoNavCrmHintPulse 2s ease-in-out infinite;
}

@keyframes papoNavCrmHintPulse {
    0%, 100% {
        outline-color: rgba(37, 99, 235, 0.35);
        box-shadow: 0 0 0 0 rgba(37, 99, 235, 0.2);
    }
    50% {
        outline-color: rgba(37, 99, 235, 0.72);
        box-shadow: 0 0 0 5px rgba(37, 99, 235, 0.14);
    }
}

.papo-nav-crm-hint {
    z-index: 1000005;
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.22s ease, transform 0.22s ease;
}

.papo-nav-crm-hint--anchored {
    position: absolute;
    left: calc(100% + 2px);
    top: 50%;
    transform: translateY(calc(-50% + 4px));
    width: max-content;
    max-width: min(12.5rem, calc(100vw - 2rem));
}

.papo-nav-crm-hint--floating {
    position: fixed;
    transform: translateY(4px);
}

.papo-nav-crm-hint.is-visible {
    opacity: 1;
    pointer-events: none;
    width: max-content;
}

.papo-nav-crm-hint.is-visible .papo-nav-crm-hint__bubble {
    pointer-events: auto;
}

.papo-nav-crm-hint--anchored.is-visible {
    transform: translateY(-50%);
}

.papo-nav-crm-hint--floating.is-visible {
    transform: translateY(0);
}

.papo-nav-crm-hint.is-leaving {
    opacity: 0;
    pointer-events: none;
}

.papo-nav-crm-hint--anchored.is-leaving {
    transform: translateY(calc(-50% + 4px));
}

.papo-nav-crm-hint--floating.is-leaving {
    transform: translateY(4px);
}

.papo-nav-crm-hint__bubble {
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: 0.375rem;
    padding: 0.4375rem 0.5rem 0.4375rem 0.5625rem;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.98);
    border: 1px solid rgba(37, 99, 235, 0.28);
    box-shadow:
        0 10px 28px -6px rgba(15, 23, 42, 0.2),
        0 0 0 1px rgba(255, 255, 255, 0.8) inset;
    color: var(--papo-ac-text, #1e293b);
    font-size: 0.6875rem;
    line-height: 1.35;
    font-weight: 600;
}

.papo-nav-crm-hint__arrow {
    position: absolute;
    width: 0;
    height: 0;
    border-style: solid;
    pointer-events: none;
    z-index: 0;
}

.papo-nav-crm-hint[data-placement="right"] .papo-nav-crm-hint__arrow {
    left: -7px;
    top: 50%;
    margin-top: -7px;
    border-width: 7px 7px 7px 0;
    border-color: transparent rgba(255, 255, 255, 0.98) transparent transparent;
    filter: drop-shadow(-1px 0 0 rgba(37, 99, 235, 0.22));
}

.papo-nav-crm-hint[data-placement="top"] .papo-nav-crm-hint__arrow {
    bottom: -7px;
    left: 50%;
    margin-left: -7px;
    border-width: 7px 7px 0 7px;
    border-color: rgba(255, 255, 255, 0.98) transparent transparent transparent;
    filter: drop-shadow(0 1px 0 rgba(37, 99, 235, 0.22));
}

.papo-nav-crm-hint__dot {
    flex-shrink: 0;
    width: 0.4375rem;
    height: 0.4375rem;
    margin-top: 0.2rem;
    border-radius: 999px;
    background: var(--papo-ac-brand, #2563eb);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18);
    animation: papoNavCrmHintDot 1.4s ease-in-out infinite;
}

@keyframes papoNavCrmHintDot {
    0%, 100% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.25); opacity: 0.85; }
}

.papo-nav-crm-hint__text {
    flex: 1;
    min-width: 0;
}

.papo-nav-crm-hint__close {
    flex-shrink: 0;
    width: 1.125rem;
    height: 1.125rem;
    margin: -0.125rem -0.0625rem 0 0;
    padding: 0;
    border: none;
    border-radius: 6px;
    background: transparent;
    color: var(--papo-ac-muted, #64748b);
    font-size: 0.875rem;
    line-height: 1;
    cursor: pointer;
}

.papo-nav-crm-hint__close:hover {
    background: rgba(15, 23, 42, 0.06);
    color: var(--papo-ac-text, #1e293b);
}

@media (max-width: 960px) {
    body.papo-account-mobile-dock .papo-account-nav__item--chat-completo.papo-nav-crm-hint-active > .papo-account-nav__link {
        outline-offset: 2px;
    }

    .papo-nav-crm-hint--floating {
        max-width: calc(100vw - 1rem);
    }

    .papo-nav-crm-hint__bubble {
        font-size: 0.65625rem;
        padding: 0.375rem 0.4375rem 0.375rem 0.5rem;
    }
}

.papo-nav-crm-hint[data-placement="left"] .papo-nav-crm-hint__arrow {
    right: -7px;
    left: auto;
    top: 50%;
    margin-top: -7px;
    border-width: 7px 0 7px 7px;
    border-color: transparent transparent transparent rgba(255, 255, 255, 0.98);
    filter: drop-shadow(1px 0 0 rgba(37, 99, 235, 0.22));
}

body.papo-nav-crm-hint-open .papo-account-shell__sidebar {
    z-index: 40;
}

body.papo-theme-glass.papo-nav-crm-hint-open .papo-nav-crm-hint[data-placement="left"] .papo-nav-crm-hint__arrow {
    border-left-color: rgba(255, 255, 255, 0.88) !important;
}


