/* Papo UI Modal — overlay padronizado (prompt, conta, etc.) */

body.papo-ui-modal-open {
    overflow: hidden;
}

.papo-ui-modal {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 1000008;
    align-items: center;
    justify-content: center;
    padding: 1rem;
    box-sizing: border-box;
}

.papo-ui-modal.is-open {
    display: flex;
}

.papo-ui-modal[hidden] {
    display: none !important;
}

.papo-ui-modal.is-open[hidden] {
    display: flex !important;
}

.papo-ui-modal__backdrop {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.5);
}

.papo-ui-modal__dialog {
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    width: min(100%, 32.5rem);
    max-height: min(88vh, 40rem);
    overflow: hidden;
    background: var(--papo-modal-bg, #fff);
    border: 1px solid var(--papo-modal-border, var(--papo-color-border, #e2e8f0));
    border-radius: var(--papo-modal-radius, 12px);
    box-shadow: var(--papo-modal-shadow, 0 24px 48px rgba(15, 23, 42, 0.2));
    box-sizing: border-box;
}

.papo-ui-modal__dialog--lg {
    width: min(100%, 62.5rem);
    max-height: min(88vh, 44rem);
}

.papo-ui-modal__dialog--form {
    width: min(100%, 37.5rem);
}

.papo-ui-modal__close {
    position: absolute;
    top: 0.625rem;
    right: 0.625rem;
    z-index: 2;
    width: 2rem;
    height: 2rem;
    padding: 0;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: var(--papo-color-muted, #64748b);
    font-size: 1.375rem;
    line-height: 1;
    cursor: pointer;
}

.papo-ui-modal__close:hover,
.papo-ui-modal__close:focus {
    color: var(--papo-color-text, #0f172a);
    background: var(--papo-color-soft, #f1f5f9);
    outline: none;
}

.papo-ui-modal__title {
    margin: 0;
    padding: 1rem 2.75rem 0.75rem 1.125rem;
    font-size: 1rem;
    font-weight: 700;
    line-height: 1.3;
    color: var(--papo-color-text, #0f172a);
    border-bottom: 1px solid var(--papo-color-border, #e2e8f0);
}

.papo-ui-modal__body {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: 0.875rem 1.125rem 1.125rem;
}

.papo-ui-modal__body--flush {
    padding-top: 0;
}

.papo-ui-modal__footer {
    display: flex;
    flex-wrap: wrap;
    gap: 0.625rem;
    justify-content: flex-end;
    padding: 0.875rem 1.125rem 1.125rem;
    border-top: 1px solid var(--papo-color-border, #e2e8f0);
}

.papo-ui-modal__btn {
    padding: 0.5625rem 1rem;
    border-radius: 8px;
    border: 1px solid transparent;
    font-size: 0.8125rem;
    font-weight: 600;
    line-height: 1.2;
    cursor: pointer;
}

.papo-ui-modal__btn--primary {
    background: var(--papo-color-brand-dark, #28a745);
    color: #fff;
}

.papo-ui-modal__btn--secondary {
    background: var(--papo-color-soft, #f1f5f9);
    color: var(--papo-color-text, #334155);
    border-color: var(--papo-color-border, #e2e8f0);
}

.papo-ui-modal__field {
    margin-bottom: 0.875rem;
}

.papo-ui-modal__field label {
    display: block;
    margin-bottom: 0.3125rem;
    font-size: 0.8125rem;
    font-weight: 600;
    color: var(--papo-color-text, #334155);
}

.papo-ui-modal__field input[type="text"],
.papo-ui-modal__field select,
.papo-ui-modal__field textarea {
    width: 100%;
    padding: 0.625rem 0.75rem;
    border: 1px solid var(--papo-color-border, #e2e8f0);
    border-radius: 8px;
    font: inherit;
    box-sizing: border-box;
}

.papo-ui-modal__field textarea {
    resize: vertical;
}

.papo-ui-modal__checkbox {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.8125rem;
}

.papo-ui-modal__code {
    background: var(--papo-color-soft, #f8fafc);
    padding: 0.875rem;
    border-radius: 8px;
    border: 1px solid var(--papo-color-border, #e2e8f0);
    font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    font-size: 0.75rem;
    line-height: 1.45;
    white-space: pre-wrap;
    max-height: 60vh;
    overflow-y: auto;
}

/* Histórico de versões */
.papo-historico-list {
    margin: 0;
    padding: 0;
    overflow-y: auto;
}

.papo-historico-list .loading,
.papo-historico-list .notice {
    padding: 0.875rem 0.5rem;
    margin: 0;
    font-size: 0.75rem;
}

.historico-item {
    border-bottom: 1px solid var(--papo-color-border, #e2e8f0);
}

.historico-item:last-child {
    border-bottom: none;
}

.historico-item-row {
    display: flex;
    align-items: stretch;
    gap: 0.5rem;
}

.historico-item-toggle {
    flex: 1;
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.625rem;
    border: none;
    background: transparent;
    cursor: pointer;
    text-align: left;
    font: inherit;
    transition: background 0.15s;
}

.historico-item-toggle:hover {
    background: var(--papo-color-soft, #fafafa);
}

.historico-item.is-open > .historico-item-row .historico-item-toggle {
    background: var(--papo-color-soft, #f8fafc);
}

.historico-item-caret {
    flex-shrink: 0;
    width: 0;
    height: 0;
    border-left: 5px solid #86efac;
    border-top: 4px solid transparent;
    border-bottom: 4px solid transparent;
    transition: transform 0.18s ease;
}

.historico-item.is-open .historico-item-caret {
    transform: rotate(90deg);
    border-left-color: var(--papo-color-brand-dark, #28a745);
}

.historico-item-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.historico-item-data {
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--papo-color-text, #1e293b);
    line-height: 1.2;
}

.historico-item-preview {
    font-size: 0.6875rem;
    color: var(--papo-color-muted, #64748b);
    line-height: 1.3;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.historico-item-meta {
    flex-shrink: 0;
    font-size: 0.625rem;
    font-weight: 600;
    color: var(--papo-color-muted, #94a3b8);
    padding: 2px 6px;
    background: var(--papo-color-soft, #f8fafc);
    border: 1px solid var(--papo-color-border, #e2e8f0);
    border-radius: 999px;
    white-space: nowrap;
}

.historico-btn-restaurar {
    align-self: center;
    margin-right: 0.5rem;
    padding: 0.3125rem 0.625rem;
    font-size: 0.6875rem;
    font-weight: 600;
    background: var(--papo-color-brand-soft, #f0fdf4);
    color: #166534;
    border: 1px solid var(--papo-color-brand-border, #bbf7d0);
    border-radius: 6px;
    cursor: pointer;
    white-space: nowrap;
    flex-shrink: 0;
}

.historico-btn-restaurar:hover {
    background: #dcfce7;
    border-color: #86efac;
}

.historico-item-detail {
    font-size: 0.6875rem;
    color: #475569;
    line-height: 1.45;
    white-space: pre-wrap;
    max-height: 8.75rem;
    overflow-y: auto;
    padding: 0 0.625rem 0.5rem 2.1rem;
    background: var(--papo-color-soft, #fafafa);
    border-top: 1px solid #f1f5f9;
}

/* Assistentes arquivados */
.papo-archived-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    max-height: 22.5rem;
    overflow-y: auto;
}

.papo-archived-list__empty {
    margin: 0;
    padding: 1rem 0.5rem;
    text-align: center;
    color: var(--papo-color-text-muted, #64748b);
    font-size: 0.8125rem;
}

.papo-archived-item {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    padding: 0.625rem 0.75rem;
    border: 1px solid var(--papo-color-border, #e2e8f0);
    border-radius: 10px;
    background: #fff;
}

.papo-archived-item__icon {
    font-size: 1.125rem;
    line-height: 1;
}

.papo-archived-item__name {
    flex: 1;
    font-size: 0.8125rem;
    font-weight: 500;
    color: var(--papo-color-text, #334155);
}

.papo-archived-item__restore {
    padding: 0.3125rem 0.625rem;
    border-radius: 999px;
    border: 1px solid var(--papo-color-border, #e2e8f0);
    background: var(--papo-color-soft, #f8fafc);
    color: var(--papo-color-text, #334155);
    font-size: 0.75rem;
    cursor: pointer;
}

.papo-archived-item__restore:hover {
    background: #eef2f7;
}

@media (max-width: 520px) {
    .historico-item-meta {
        display: none;
    }

    .historico-item-row {
        flex-wrap: wrap;
    }

    .historico-btn-restaurar {
        margin: 0 0.5rem 0.5rem auto;
    }
}

